{
  "implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    INF_NEG = -float('inf')
    dp = [[None for _ in range(budget+1)] for _ in range(n+1)]
    dp[0][0] = (0.0, ())
    for i in range(1, n+1):
        l = lengths[i-1]
        s = scores[i-1]
        for t in range(budget+1):
            best = dp[i-1][t]  # not take
            if t >= l and dp[i-1][t-l] is not None:
                prev_score, prev_indices = dp[i-1][t-l]
                new_score = prev_score + s
                new_indices = prev_indices + (i-1,)
                if best is None:
                    best = (new_score, new_indices)
                else:
                    cur_score, cur_indices = best
                    if new_score > cur_score or (new_score == cur_score and new_indices < cur_indices):
                        best = (new_score, new_indices)
            dp[i][t] = best
    best_score = INF_NEG
    best_t = None
    best_indices = None
    for t in range(budget+1):
        entry = dp[n][t]
        if entry is None:
            continue
        score, indices = entry
        if score > best_score or (score == best_score and (best_t is None or t < best_t)):
            best_score = score
            best_t = t
            best_indices = indices
    if best_indices is None:
        return {"selected_indices": [], "tokens_used": 0, "total_score": 0.0}
    return {"selected_indices": list(best_indices), "tokens_used": best_t, "total_score": best_score}"
}
